package dev.relay;
import dev.relay.domain.*;import dev.relay.repo.WorkflowRepository;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.Container;import org.testcontainers.junit.jupiter.Testcontainers;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Testcontainers(disabledWithoutDocker = true)
class WorkflowRepositoryIT {
 @Container static PostgreSQLContainer<?> db=new PostgreSQLContainer<>("postgres:16-alpine");
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",db::getJdbcUrl);r.add("spring.datasource.username",db::getUsername);r.add("spring.datasource.password",db::getPassword);r.add("relay.poll-ms",()->"3600000");r.add("relay.workers.enabled",()->"false");}
 @Autowired WorkflowRepository repo; @Autowired dev.relay.engine.OrderActivityService activities; @Autowired org.springframework.jdbc.core.JdbcTemplate jdbc; @Autowired com.fasterxml.jackson.databind.ObjectMapper mapper;
 @Test void idempotencyReturnsSameWorkflow(){String key=UUID.randomUUID().toString();var req=new CreateWorkflowRequest("demo",key,Map.of("x",1),List.of(new CreateWorkflowRequest.Step("noop",Map.of())),3);var a=repo.create(req);var b=repo.create(req);assertEquals(a.id(),b.id());assertEquals(1,repo.steps(a.id()).size());}
 @Test void historyIsAppendOnlyAndOrdered(){String key=UUID.randomUUID().toString();var w=repo.create(new CreateWorkflowRequest("demo",key,Map.of(),List.of(new CreateWorkflowRequest.Step("noop",Map.of())),3));repo.record(w.id(),"TEST_EVENT",0,1,"test",1,Map.of());assertEquals("CREATED",repo.history(w.id()).get(0).get("event_type"));assertEquals("TEST_EVENT",repo.history(w.id()).get(1).get("event_type"));}

 @Test void orderEffectsAreIdempotentAcrossRetry()throws Exception{String oid="order-"+UUID.randomUUID();var req=new CreateWorkflowRequest("demo",oid,Map.of("orderId",oid,"customerName","Test Customer","email","test@example.com","sku","KEYBOARD","quantity",2,"amount","99.00","paymentScenario","FAIL_ONCE"),List.of(new CreateWorkflowRequest.Step("reserve-inventory",Map.of()),new CreateWorkflowRequest.Step("charge-payment",Map.of())),3);var w=repo.create(req);var input=mapper.valueToTree(req.input());int before=jdbc.queryForObject("select available from inventory_items where sku='KEYBOARD'",Integer.class);activities.reserve(w.id(),input);activities.reserve(w.id(),input);assertEquals(before-2,jdbc.queryForObject("select available from inventory_items where sku='KEYBOARD'",Integer.class));assertThrows(dev.relay.engine.ActivityRunner.SimulatedFailure.class,()->activities.charge(w.id(),input,1));activities.charge(w.id(),input,2);activities.charge(w.id(),input,2);assertEquals(1,jdbc.queryForObject("select count(*) from payments where workflow_id=?",Integer.class,w.id()));}

 @Test void compensationReleasesReservedStockOnce()throws Exception{String oid="comp-"+UUID.randomUUID();var req=new CreateWorkflowRequest("demo",oid,Map.of("orderId",oid,"customerName","Test Customer","email","test@example.com","sku","HEADPHONES","quantity",3,"amount","75.00","paymentScenario","DECLINE"),List.of(new CreateWorkflowRequest.Step("reserve-inventory",Map.of())),3);var w=repo.create(req);var input=mapper.valueToTree(req.input());int before=jdbc.queryForObject("select available from inventory_items where sku='HEADPHONES'",Integer.class);activities.reserve(w.id(),input);assertTrue(activities.compensate(w.id()));assertFalse(activities.compensate(w.id()));assertEquals(before,jdbc.queryForObject("select available from inventory_items where sku='HEADPHONES'",Integer.class));assertEquals("RELEASED",jdbc.queryForObject("select status from inventory_reservations where workflow_id=?",String.class,w.id()));}
}
